+test('restored version record tampering is detected against retained immutable fingerprint',()=>{
+  const {g,store}=populatedStore();
+  const snap=store.snapshot();
+  snap.versions['CLP-001-TRANSITIONS@1.0.0']={forged:true};
+  const tampered=GovernanceStore.fromSnapshot(snap);
+  assert.throws(()=>replayPersistedCase(g.correlation_id,tampered),/version hash mismatch/);
+});
+
+test('chain ordinals are scoped per correlation and two cases may each start at ordinal one',()=>{
+  const store=new GovernanceStore();
+  const a={ordinal:1,event_id:'evt-a',event_hash:'sha256:a',previous_chain_hash:null,chain_hash:'sha256:ca'};
+  const b={ordinal:1,event_id:'evt-b',event_hash:'sha256:b',previous_chain_hash:null,chain_hash:'sha256:cb'};
+  assert.equal(store.appendChainRecord(a).status,'APPENDED');
+  assert.equal(store.appendChainRecord(b).status,'APPENDED');
+});
+
